labeled_query:
SELECT ?decade (COUNT(?person) AS ?totalDeaths) (SUM(?isTB) AS ?tbDeaths) ((SUM(?isTB) * 100.0 / COUNT(?person)) AS ?percentage) WHERE {
  ?person wdt:[property:instance of] wd:[entity:human] .
  ?person wdt:[property:date of death] ?deathDate .
  BIND(FLOOR(YEAR(?deathDate) / 10) * 10 AS ?decade)
  OPTIONAL {
    ?person wdt:[property:cause of death] ?cause .
    FILTER(?cause = wd:[entity:tuberculosis])
    BIND(1 AS ?tbFlag)
  }
  BIND(IF(BOUND(?tbFlag), 1, 0) AS ?isTB)
}
GROUP BY ?decade
ORDER BY ?decade

linked_query:
