  ?person wdt:P31 wd:Q5 .
  ?person wdt:P570 ?deathDate .
  BIND(FLOOR(YEAR(?deathDate) / 10) * 10 AS ?decade)
  OPTIONAL {
    ?person wdt:P509 ?cause .
    FILTER(?cause = wd:Q12204)
    BIND(1 AS ?tbFlag)
  }
  BIND(IF(BOUND(?tbFlag), 1, 0) AS ?isTB)
}
GROUP BY ?decade
ORDER BY ?decade

