SELECT DISTINCT ?musician ?musicianLabel WHERE {
  ?musician wdt:[property:instance of] wd:[entity:human] .
  ?musician wdt:[property:occupation] wd:[entity:musician] .
  ?musician wdt:[property:date of birth] ?birth .
  ?musician wdt:[property:date of death] ?death .
  BIND(YEAR(?death) - YEAR(?birth) - IF(MONTH(?death) < MONTH(?birth) || (MONTH(?death) = MONTH(?birth) && DAY(?death) < DAY(?birth)), 1, 0) AS ?age)
  FILTER(?age = 27)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

