SELECT ?term ?termLabel (COUNT(DISTINCT ?woman) AS ?numWomen) (COUNT(DISTINCT ?john) AS ?numJohns) WHERE {
  ?term wdt:[property:instance of] wd:[entity:term of the Parliament of the United Kingdom] .
  ?term wdt:[property:start time] ?start .
  FILTER(YEAR(?start) >= 1992)

  OPTIONAL {
    ?statementWoman ps:[property:position held] wd:[entity:Member of Parliament of the United Kingdom] .
    ?woman p:[property:position held] ?statementWoman .
    ?statementWoman pq:[property:parliamentary term] ?term .
    ?woman wdt:[property:sex or gender] wd:[entity:female] .
  }

  OPTIONAL {
    ?statementJohn ps:[property:position held] wd:[entity:Member of Parliament of the United Kingdom] .
    ?john p:[property:position held] ?statementJohn .
    ?statementJohn pq:[property:parliamentary term] ?term .
    ?john wdt:[property:given name] wd:[entity:John] .
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?term ?termLabel
ORDER BY ?termLabel

